import { Controller, Get, Post, Put, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const AMOUNT_EXCEEDED = 'ASSET_ITEM_AMOUNT_EXCEEDED';

function idOf(value: unknown, label: string): string {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function parseItem(data: Record<string, unknown>) {
  const rawName = data['itemName'];
  const itemName = typeof rawName === 'string' ? rawName.trim() : '';
  if (itemName === '' || itemName.length > 200) {
    throw new ApiError(422, AMOUNT_EXCEEDED, '품목명을 200자 이내로 입력해 주세요.');
  }
  const rawQuantity = data['quantity'];
  const quantity = typeof rawQuantity === 'number' ? rawQuantity : NaN;
  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new ApiError(422, AMOUNT_EXCEEDED, '수량은 1 이상의 정수로 입력해 주세요.');
  }
  const rawPrice = data['unitPrice'];
  const hasPrice = typeof rawPrice === 'number' || (typeof rawPrice === 'string' && rawPrice.trim() !== '');
  const unitPrice = hasPrice ? Number(rawPrice) : NaN;
  if (!Number.isFinite(unitPrice) || unitPrice < 0) {
    throw new ApiError(422, AMOUNT_EXCEEDED, '단가는 0 이상의 숫자로 입력해 주세요.');
  }
  return { itemName, quantity, unitPrice };
}

function isApproved(status: unknown): boolean {
  // 가정: 승인 완료 상태는 '승인', '완료'
  return status === '승인' || status === '완료';
}

@Controller('api/v1')
export class FnSfr02404Controller {
  @Get('/purchase-asset-items')
  async listPurchaseAssetItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const purchaseRequestId = idOf(query['purchaseRequestId'], '품의서');
    const pageNo = Math.max(0, Number.parseInt(String(query['page'] ?? '0'), 10) || 0);
    const size = Math.min(200, Math.max(1, Number.parseInt(String(query['size'] ?? '20'), 10) || 20));
    return transaction(async (db) => {
      const params = { purchaseRequestId, size, offset: pageNo * size };
      const items = await db.query(
        `SELECT i.purchase_asset_item_id AS "purchaseAssetItemId",
                i.item_name AS "itemName",
                i.quantity AS "quantity",
                i.unit_price AS "unitPrice",
                i.amount AS "amount",
                r.asset_inspection_required AS "assetInspectionRequired"
           FROM purchase_asset_item i
           JOIN purchase_request r ON r.purchase_request_id = i.purchase_request_id
          WHERE i.purchase_request_id = CAST(:purchaseRequestId AS bigint)
          ORDER BY i.purchase_asset_item_id
          LIMIT :size OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM purchase_asset_item
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)`,
        { purchaseRequestId },
      );
      return { items, page: pageNo, size, total: Number(counts[0]?.total ?? 0) };
    });
  }

  @Post('/purchase-asset-items')
  @HttpCode(200)
  async createPurchaseAssetItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const purchaseRequestId = idOf(data['purchaseRequestId'], '품의서');
    const item = parseItem(data);
    return transaction(async (db) => {
      const requests = await db.query(
        `SELECT approval_status AS "approvalStatus"
           FROM purchase_request
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)`,
        { purchaseRequestId },
      );
      if (requests.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      if (isApproved(requests[0].approvalStatus)) {
        throw new ApiError(409, 'PURCHASE_REQUEST_APPROVED', '승인 완료된 품의서의 자산품목은 등록할 수 없습니다.');
      }
      const checkRows = await db.query(
        `SELECT (COALESCE(SUM(amount), 0) + CAST(:quantity AS integer) * CAST(:unitPrice AS numeric)
                 > (SELECT amount FROM purchase_request WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint))) AS "exceeded"
           FROM purchase_asset_item
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)`,
        { purchaseRequestId, quantity: item.quantity, unitPrice: item.unitPrice },
      );
      if (checkRows[0]?.exceeded === true) {
        throw new ApiError(422, AMOUNT_EXCEEDED, '자산품목 금액 합계가 품의 금액을 초과할 수 없습니다.');
      }
      const rows = await db.query(
        `INSERT INTO purchase_asset_item
           (purchase_request_id, item_name, quantity, unit_price, amount, created_at, updated_at)
         VALUES
           (CAST(:purchaseRequestId AS bigint), :itemName, CAST(:quantity AS integer), CAST(:unitPrice AS numeric),
            CAST(:quantity AS integer) * CAST(:unitPrice AS numeric), now(), now())
         RETURNING purchase_asset_item_id AS "purchaseAssetItemId", amount AS "amount"`,
        { purchaseRequestId, itemName: item.itemName, quantity: item.quantity, unitPrice: item.unitPrice },
      );
      return rows[0];
    });
  }

  @Put('/purchase-asset-items/:purchaseAssetItemId')
  async updatePurchaseAssetItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const purchaseAssetItemId = idOf(req.params['purchaseAssetItemId'], '자산품목');
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const item = parseItem(data);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT i.purchase_request_id AS "purchaseRequestId", r.approval_status AS "approvalStatus"
           FROM purchase_asset_item i
           JOIN purchase_request r ON r.purchase_request_id = i.purchase_request_id
          WHERE i.purchase_asset_item_id = CAST(:purchaseAssetItemId AS bigint)`,
        { purchaseAssetItemId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PURCHASE_ASSET_ITEM_NOT_FOUND', '자산품목을 찾을 수 없습니다.');
      }
      if (isApproved(found[0].approvalStatus)) {
        throw new ApiError(409, 'PURCHASE_REQUEST_APPROVED', '승인 완료된 품의서의 자산품목은 수정할 수 없습니다.');
      }
      const purchaseRequestId = String(found[0].purchaseRequestId);
      const checkRows = await db.query(
        `SELECT (COALESCE(SUM(amount), 0) + CAST(:quantity AS integer) * CAST(:unitPrice AS numeric)
                 > (SELECT amount FROM purchase_request WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint))) AS "exceeded"
           FROM purchase_asset_item
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)
            AND purchase_asset_item_id <> CAST(:purchaseAssetItemId AS bigint)`,
        { purchaseRequestId, purchaseAssetItemId, quantity: item.quantity, unitPrice: item.unitPrice },
      );
      if (checkRows[0]?.exceeded === true) {
        throw new ApiError(422, AMOUNT_EXCEEDED, '자산품목 금액 합계가 품의 금액을 초과할 수 없습니다.');
      }
      const rows = await db.query(
        `UPDATE purchase_asset_item
            SET item_name = :itemName,
                quantity = CAST(:quantity AS integer),
                unit_price = CAST(:unitPrice AS numeric),
                amount = CAST(:quantity AS integer) * CAST(:unitPrice AS numeric),
                updated_at = now()
          WHERE purchase_asset_item_id = CAST(:purchaseAssetItemId AS bigint)
          RETURNING purchase_asset_item_id AS "purchaseAssetItemId", amount AS "amount"`,
        { purchaseAssetItemId, itemName: item.itemName, quantity: item.quantity, unitPrice: item.unitPrice },
      );
      return rows[0];
    });
  }

  @Patch('/purchase-requests/:purchaseRequestId/asset-inspection')
  async setPurchaseRequestAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '자산 담당자');
    const purchaseRequestId = idOf(req.params['purchaseRequestId'], '품의서');
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const required = data['assetInspectionRequired'];
    if (typeof required !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산 검수 여부를 선택해 주세요.');
    }
    return transaction(async (db) => {
      const requests = await db.query(
        `SELECT approval_status AS "approvalStatus"
           FROM purchase_request
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)`,
        { purchaseRequestId },
      );
      if (requests.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      if (isApproved(requests[0].approvalStatus)) {
        throw new ApiError(409, 'PURCHASE_REQUEST_APPROVED', '승인 완료된 품의서의 검수 여부는 설정할 수 없습니다.');
      }
      const rows = await db.query(
        `UPDATE purchase_request
            SET asset_inspection_required = :required,
                updated_at = now()
          WHERE purchase_request_id = CAST(:purchaseRequestId AS bigint)
          RETURNING purchase_request_id AS "purchaseRequestId", asset_inspection_required AS "assetInspectionRequired"`,
        { purchaseRequestId, required },
      );
      return rows[0];
    });
  }
}

