import { useState } from 'react';
import {
  call, useData, Badge, Num, Filters, Band, DataTable, Pager, Drawer, Tiles, Form, Field,
  TextInput, NumberInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr02404Page({ role, notify }: PageProps) {
  const [requestId, setRequestId] = useState<number | string>('');
  const [applied, setApplied] = useState<number | string>('');
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<'' | 'create' | 'edit' | 'inspection'>('');
  const [target, setTarget] = useState<Row | null>(null);
  const [itemName, setItemName] = useState('');
  const [quantity, setQuantity] = useState<number | string>('');
  const [unitPrice, setUnitPrice] = useState<number | string>('');
  const [inspection, setInspection] = useState('false');

  const { data, error, reload } = useData<Page | null>(async () => {
    if (applied === '') return null;
    return call<Page>('GET', '/purchase-asset-items', role, undefined, {
      purchaseRequestId: applied,
      page: pageNo,
      size: 20,
    });
  }, [applied, pageNo, role]);

  const rows: Row[] = data ? data.items : [];
  const sumAmount = rows.reduce((acc, row) => acc + Number(row['amount'] ?? 0), 0);
  const inspectionOn = rows.length > 0 ? rows[0]['assetInspectionRequired'] === true : false;

  function close() {
    setMode('');
    setTarget(null);
  }

  function openCreate() {
    if (applied === '') {
      notify('품의서를 먼저 조회해 주세요.');
      return;
    }
    setItemName('');
    setQuantity('');
    setUnitPrice('');
    setMode('create');
  }

  function openEdit(row: Row) {
    setTarget(row);
    setItemName(String(row['itemName'] ?? ''));
    setQuantity(Number(row['quantity'] ?? 0));
    setUnitPrice(Number(row['unitPrice'] ?? 0));
    setMode('edit');
  }

  function openInspection() {
    if (applied === '') {
      notify('품의서를 먼저 조회해 주세요.');
      return;
    }
    setInspection(inspectionOn ? 'true' : 'false');
    setMode('inspection');
  }

  function checkInputs() {
    if (itemName.trim() === '' || quantity === '' || unitPrice === '') {
      throw new Error('품목명, 수량, 단가를 모두 입력해 주세요.');
    }
  }

  async function submitCreate() {
    checkInputs();
    await call('POST', '/purchase-asset-items', role, {
      purchaseRequestId: applied,
      itemName: itemName.trim(),
      quantity,
      unitPrice,
    });
    notify('자산품목을 등록했습니다.');
    close();
    reload();
  }

  async function submitEdit() {
    checkInputs();
    await call('PUT', `/purchase-asset-items/${target?.['purchaseAssetItemId']}`, role, {
      itemName: itemName.trim(),
      quantity,
      unitPrice,
    });
    notify('자산품목을 수정했습니다.');
    close();
    reload();
  }

  async function submitInspection() {
    await call('PATCH', `/purchase-requests/${applied}/asset-inspection`, role, {
      assetInspectionRequired: inspection === 'true',
    });
    notify('자산 검수 여부를 설정했습니다.');
    close();
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>자산품목 현황</h2>
        <Tiles
          items={[
            ['자산품목 수', <Num value={data ? data.total : 0} />],
            ['금액 합계', <Num value={sumAmount} />],
            ['자산 검수', applied === '' ? '-' : inspectionOn ? '대상' : '비대상'],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>구매품의 자산품목</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied(requestId);
          }}
          onReset={() => {
            setRequestId('');
            setApplied('');
            setPageNo(0);
          }}
        >
          <Field label="품의서" required>
            <LookupSelect table="purchase_request" role={role} value={requestId} onChange={setRequestId} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>자산품목 등록</button>
          <button type="button" onClick={openInspection}>자산 검수 여부 설정</button>
        </Band>
        <DataTable
          columns={[
            { key: 'purchaseAssetItemId', label: '품의 자산품목 ID' },
            { key: 'itemName', label: '품목명' },
            { key: 'quantity', label: '수량', render: (row: Row) => <Num value={row['quantity']} /> },
            { key: 'unitPrice', label: '단가', render: (row: Row) => <Num value={row['unitPrice']} /> },
            { key: 'amount', label: '금액', render: (row: Row) => <Num value={row['amount']} /> },
            {
              key: 'assetInspectionRequired',
              label: '자산 검수 여부',
              render: (row: Row) => <Badge value={row['assetInspectionRequired'] === true ? '대상' : '비대상'} />,
            },
            {
              key: 'actions',
              label: '처리',
              render: (row: Row) => (
                <button type="button" onClick={() => openEdit(row)}>수정</button>
              ),
            },
          ]}
          rows={rows}
          empty={applied === '' ? '품의서를 선택하고 조회해 주세요.' : '등록된 자산품목이 없습니다.'}
        />
        <Pager page={pageNo} size={20} total={data ? data.total : 0} onPage={setPageNo} />
      </section>

      {mode === 'create' ? (
        <Drawer title="자산품목 등록" onClose={close}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="품의서">
              <RefName table="purchase_request" role={role} value={applied} />
            </Field>
            <Field label="품목명" required>
              <TextInput value={itemName} onChange={setItemName} />
            </Field>
            <Field label="수량" required>
              <NumberInput value={quantity} onChange={setQuantity} />
            </Field>
            <Field label="단가" required>
              <NumberInput value={unitPrice} onChange={setUnitPrice} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode === 'edit' ? (
        <Drawer title="자산품목 수정" onClose={close}>
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="품목명" required>
              <TextInput value={itemName} onChange={setItemName} />
            </Field>
            <Field label="수량" required>
              <NumberInput value={quantity} onChange={setQuantity} />
            </Field>
            <Field label="단가" required>
              <NumberInput value={unitPrice} onChange={setUnitPrice} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode === 'inspection' ? (
        <Drawer title="자산 검수 여부 설정" onClose={close}>
          <Form onSubmit={submitInspection} submit="설정">
            <Field label="품의서">
              <RefName table="purchase_request" role={role} value={applied} />
            </Field>
            <Field label="자산 검수 여부" required>
              <Select
                value={inspection}
                onChange={setInspection}
                options={[['true', '대상'], ['false', '비대상']]}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
